#pragma once#include <rsuErr.h>#include <stdlib.h>#include "FscTypes.h"struct IStateSer{  template<class T> DWORD Write( const T &obj )  {    return WriteImpl( &obj, sizeof(obj) );  }  DWORD Write( const void *pObj, DWORD objSize )  {    return WriteImpl( pObj, objSize );  }  DWORD Write( LPSTR pStr )  {    return Write( (LPCSTR)pStr );  }  virtual DWORD Write( LPCSTR pStr )  {    DWORD start = GetPosition();    DWORD l = (DWORD)strlen( pStr )+1;    Write( l );    WriteImpl( pStr, l );    DWORD end = GetPosition();    return end - start;  }  template<typename T>  bool CompareOnRead( T mask, T *pRead = NULL )  {    T read;    DWORD r = Read( read );    if( !r )      return false;    if( pRead )      *pRead = read;    if( mask!=read )      return false;    return true;  }  template<typename T> DWORD Read( T &obj )  {    return ReadImpl( &obj, sizeof(obj) );  }  template<size_t _S> DWORD Read( char (&str)[_S] )  {    return Read( str, (DWORD)_S );  }  virtual DWORD Read( char *pszBuf, DWORD size )  {    DWORD l = 0;    if( !Read( l ) )      return 0;    ASS( l<=size );    l = __min( l, size );    if( !ReadImpl( (void*)pszBuf, l ) )      return 0;    if( l > 0 )      pszBuf[l-1] = 0;    return l;  }  virtual DWORD GetPosition() = 0;  template<class T> DWORD WriteAtPosition( DWORD shiftFromBegin, const T &obj )  {    return WriteAtPositionImpl( shiftFromBegin, &obj, sizeof(obj) );  }  virtual void Skip( DWORD shift ) = 0;  virtual DWORD RawRead( void *pOut, DWORD objSize ) = 0;  virtual void WriteDotV( SDotValue *pV, LPCSTR pszName ) = 0;  virtual int ReadDotV( SDotValue *pV, LPCSTR pszName ) = 0;  virtual void SetSavedVersionFormat( DWORD v ) = 0;  virtual DWORD GetSavedVersionFormat() = 0;protected:  virtual DWORD WriteAtPositionImpl( DWORD shiftFromBegin, const void *pObj, DWORD objSize ) = 0;  virtual DWORD WriteImpl( const void *pObj, DWORD objSize ) = 0;  virtual DWORD ReadImpl( void *pOut, DWORD objSize ) = 0;};